#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;

ull power(ull b, ull e, ull mod) {
    ull r = 1;
    b %= mod;
    while (e) {
        if (e & 1) r = r * b % mod;
        b = b * b % mod;
        e >>= 1;
    }
    return r;
}

long long discreteLog(ull p, ull g, ull h) {
    if (h == 1) return 0;
    ull m = (ull)sqrtl((long double)p) + 1;   // m*m > p
    unordered_map<ull, ull> table;
    table.reserve(m * 2);
    ull cur = h % p;
    for (ull j = 0; j < m; j++) {             // 小步：相同值保留較大的 j
        table[cur] = j;
        cur = cur * g % p;
    }
    ull big = power(g, m, p);
    cur = 1;
    for (ull i = 1; i <= m; i++) {            // 大步
        cur = cur * big % p;
        auto it = table.find(cur);
        if (it != table.end()) return (long long)(m * i - it->second);
    }
    return -1;
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        ull p, g, h;
        cin >> p >> g >> h;
        cout << discreteLog(p, g, h) << '\n';
    }
    return 0;
}

