import sys
from functools import lru_cache


def count_upto(x):
    """回傳 1..x 中的跳躍數個數。"""
    if x <= 0:
        return 0
    digits = list(map(int, str(x)))
    n = len(digits)

    @lru_cache(maxsize=None)
    def go(pos, prev, tight, started):
        # prev：上一位數字（尚未開始時為 -1）；tight：前面是否與 x 完全相同
        if pos == n:
            return 1 if started else 0
        limit = digits[pos] if tight else 9
        total = 0
        for d in range(limit + 1):
            nt = tight and d == limit
            if not started:
                if d == 0:
                    total += go(pos + 1, -1, nt, False)  # 仍是前導零
                else:
                    total += go(pos + 1, d, nt, True)
            elif abs(d - prev) >= 2:
                total += go(pos + 1, d, nt, True)
        return total

    return go(0, -1, True, False)


