        while (ms.size() - head >= 2) {
            size_t t = ms.size();
            ll m1 = ms[t - 2], b1 = bs[t - 2], m2 = ms[t - 1], b2 = bs[t - 1];
            // 以 long long 做交叉相乘，數值最大約 1.6e16，不會溢位
            if ((b3 - b1) * (m1 - m2) <= (b2 - b1) * (m1 - m3)) {
                ms.pop_back();
                bs.pop_back();
            } else break;
        }
        ms.push_back(m3);
        bs.push_back(b3);
    }
    cout << dp[n] << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007LL;

int main() {
    int n;
    string s;
    cin >> n >> s;
    // dp[j]：最後一個數在目前所有數中名次為 j（0 起算）的方法數
    vector<long long> dp(1, 1);
    for (int i = 1; i <= n; i++) {
        int size = dp.size();
        vector<long long> pre(size + 1, 0);
        for (int k = 0; k < size; k++) pre[k + 1] = (pre[k] + dp[k]) % MOD;
        vector<long long> nd(size + 1, 0);
        for (int j = 0; j <= size; j++) {
            if (s[i - 1] == 'I') nd[j] = pre[j];                      // 上一個名次 k < j
            else nd[j] = ((pre[size] - pre[j]) % MOD + MOD) % MOD;    // 上一個名次 k >= j
        }
        dp = nd;
    }
    long long ans = 0;
    for (long long v : dp) ans = (ans + v) % MOD;
    cout << ans << '\n';
    return 0;
}
